plugin_commands_mz3d.registerCommand = function (name, argsFunc, execFunc) {
  const lowercaseName = String(name).toLowerCase();

  if (typeof PluginManager.registerCommand === 'function') {
    if (typeof argsFunc === 'function') {
      PluginManager.registerCommand('mz3d', name, function (args) {waitPluginCommand(this, execFunc.call(this, args));});
    } else if (typeof argsFunc === 'object') {
      PluginManager.registerCommand('mz3d', name, plugin_commands_mz3d.registerCommand.executeWithTypes(execFunc, argsFunc.types || {}));
    }
  }

  if (typeof argsFunc === 'function') {
    const commandFunc = function (...args) {
      return execFunc.call(this.INTERPRETER, argsFunc.call(this.INTERPRETER, ...args));
    };
    plugin_commands_mz3d.PluginCommand.prototype[lowercaseName] = commandFunc;
  } else if (typeof argsFunc === 'object') {
    const commandFunc = function (...args) {
      return execFunc.call(this.INTERPRETER, this.getKeywords(args, argsFunc.types || {}, argsFunc.aliases || []));
    };
    plugin_commands_mz3d.PluginCommand.prototype[lowercaseName] = commandFunc;
  }

};

plugin_commands_mz3d.registerCommand.executeWithTypes = function (execFunc, types) {
  types = Object.assign({}, plugin_commands_mz3d.PluginCommand.defaultTypes, types);
  return function (args) {
    const typedArgs = {};
    for (const key in args) {
      const arg = args[key];
      switch (types[key]) {
        case String:
        case undefined:
          typedArgs[key] = String(arg);
          break;
        case Boolean:
          typedArgs[key] = (0,util.booleanString)(arg);
          break;
        case characters/* Character */.z:
          typedArgs[key] = plugin_commands_mz3d.targetChar(arg, $gameMap.event(this._eventId), this.CHAR);
          break;
        default:
          typedArgs[key] = types[key](arg);}

    }
    waitPluginCommand(this, execFunc.call(this, typedArgs));
  };
};

