plugin_commands_mz3d.registerCommand('action', {
  types: { loop: Boolean, important: Boolean },
  aliases: ['playback', 'name'] },
async (args) => {
  if (!args.playback || !args.name) return;
  const name = args.name.toLowerCase();
  const sprite = args.target.mv3d_sprite;
  if (!sprite) return;
  switch (args.playback.toLowerCase()) {
    case 'play':
      sprite.playAction(name, args.loop, args.important);
      if (args.wait) await sprite.waitForAction(name);
      break;
    case 'stop':
      sprite.stopAction(name);
      break;
    case 'pause':
      sprite.pauseAction(name);
      break;}

});
